let datePickerMonth=new Date();
function calendarMarkup(value){const selected=value?new Date(value+'T12:00:00'):null;const y=datePickerMonth.getFullYear(),m=datePickerMonth.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=first.getDay();const monthLabel=first.toLocaleDateString('ar-QA',{month:'long',year:'numeric'});const weekdays=['الأحد','الإثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];let cells=weekdays.map(d=>`<span class="date-weekday">${d}</span>`).join('');for(let i=0;i<offset;i++)cells+='<span class="date-empty"></span>';for(let day=1;day<=days;day++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,todayFlag=date===today(),chosen=value===date;cells+=`<button type="button" class="date-day ${todayFlag?'is-today':''} ${chosen?'is-selected':''}" data-pick-date="${date}">${day}</button>`}return `<div class="date-picker"><div class="date-picker-head"><button type="button" data-month-step="-1" aria-label="الشهر السابق">‹</button><strong>${monthLabel}</strong><button type="button" data-month-step="1" aria-label="الشهر التالي">›</button></div><div class="date-picker-grid">${cells}</div><div class="date-picker-foot"><button type="button" data-date-today>اليوم</button><button type="button" data-date-clear>مسح التاريخ</button></div></div>`}
function refreshDatePicker(){const wrap=$('#datePickerWrap');if(!wrap)return;const input=wrap.querySelector('input[name=date]');wrap.querySelector('.date-picker-host').innerHTML=calendarMarkup(input.value)}
function openForm(id){editing=id||null;pendingMedia=[];clearPendingPreviews();const cfg=sections[page],item=id?store.get(page).find(x=>x.id===id)||{}:{};$('#modalTitle').textContent=id?'تعديل':'إضافة';$('#formFields').innerHTML=cfg.fields.map(([name,label,type,required,opts])=>{if(type==='textarea')return `<label class="field">${label}<textarea name="${name}" ${required?'required':''}>${esc(item[name]||'')}</textarea></label>`;if(type==='select')return `<label class="field">${label}<select name="${name}"><option value="">اختاري التصنيف</option>${opts.map(o=>`<option ${item[name]===o?'selected':''}>${o}</option>`).join('')}</select></label>`;if(type==='file')return `<label class="field">${label}<input name="${name}" type="file" accept="image/*,video/*" ${id?'':'multiple'} ${id?'':'required'}><small>يمكنكِ تحديد عدة صور وفيديوهات معاً. الحد الأقصى 100 ميغابايت للملف الواحد و10 ملفات في المرة الواحدة.</small><div id="mediaSelectionPreview" class="media-selection-preview"></div></label>`;if(name==='date')return `<label class="field">${label}<div id="datePickerWrap" class="date-picker-wrap"><input type="hidden" name="date" value="${esc(item.date||'')}"><button type="button" class="date-picker-trigger" data-open-calendar><span>▦</span><strong>${item.date?'التاريخ المختار: '+dateText(item.date):'اختاري تاريخ المهمة'}</strong><i>⌄</i></button><div class="date-picker-host">${calendarMarkup(item.date||'')}</div></div></label>`;return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(item[name]||'')}" ${required?'required':''} ></label>`}).join('');$('#modal').classList.remove('hidden');datePickerMonth=item.date?new Date(item.date+'T12:00:00'):new Date();const dateWrap=$('#datePickerWrap');if(dateWrap){dateWrap.querySelector('.date-picker-host').classList.add('is-open');dateWrap.addEventListener('click',e=>{const step=e.target.closest('[data-month-step]');if(step){datePickerMonth.setMonth(datePickerMonth.getMonth()+Number(step.dataset.monthStep));refreshDatePicker();return}const pick=e.target.closest('[data-pick-date]');if(pick){const value=pick.dataset.pickDate;dateWrap.querySelector('input[name=date]').value=value;dateWrap.querySelector('.date-picker-trigger strong').textContent='التاريخ المختار: '+dateText(value);refreshDatePicker();dateWrap.querySelector('.date-picker-host').classList.remove('is-open');return}if(e.target.closest('[data-date-today]')){const value=today();datePickerMonth=new Date(value+'T12:00:00');dateWrap.querySelector('input[name=date]').value=value;dateWrap.querySelector('.date-picker-trigger strong').textContent='التاريخ المختار: '+dateText(value);refreshDatePicker();dateWrap.querySelector('.date-picker-host').classList.remove('is-open');return}if(e.target.closest('[data-date-clear]')){dateWrap.querySelector('input[name=date]').value='';dateWrap.querySelector('.date-picker-trigger strong').textContent='اختاري تاريخ المهمة';refreshDatePicker();return}if(e.target.closest('[data-open-calendar]'))dateWrap.querySelector('.date-picker-host').classList.toggle('is-open')})}const file=$('#formFields input[type=file]');if(file)file.addEventListener('change',()=>{clearPendingPreviews();const chosen=Array.from(file.files||[]);if(chosen.length>10){toast('يمكنكِ اختيار 10 ملفات كحد أقصى في المرة الواحدة');file.value='';return}for(const f of chosen){if(f.size>100*1024*1024){toast(`الملف ${f.name} أكبر من 100 ميغابايت`);file.value='';pendingMedia=[];clearPendingPreviews();return}if(!f.type.startsWith('image/')&&!f.type.startsWith('video/')){toast('اختاري صوراً أو فيديوهات فقط');file.value='';pendingMedia=[];clearPendingPreviews();return}}pendingMedia=chosen;const preview=$('#mediaSelectionPreview');if(preview){preview.innerHTML=chosen.map((f,i)=>{const url=URL.createObjectURL(f);pendingPreviewUrls.push(url);return `<div class="media-selected-item">${f.type.startsWith('video/')?`<video src="${url}" muted playsinline></video>`:`<img src="${url}" alt="معاينة">`}<span>${esc(f.name)} · ${formatBytes(f.size)}</span></div>`}).join('')} });if(id&&item.mediaId){const note=document.createElement('small');note.className='field-note';note.textContent='اتركي اختيار الملف فارغاً للاحتفاظ بالملف الحالي، أو اختاري ملفاً جديداً لاستبداله.';$('#mediaSelectionPreview')?.append(note)}}
function formatBytes(bytes){if(!bytes)return '0 بايت';const units=['بايت','KB','MB','GB'];let n=bytes,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${units[i]}`}
function clearPendingPreviews(){pendingPreviewUrls.forEach(u=>URL.revokeObjectURL(u));pendingPreviewUrls=[]}
function closeForm(){$('#modal').classList.add('hidden');editing=null;pendingMedia=[];clearPendingPreviews()}$('#closeModal').onclick=closeForm;$('#cancelModal').onclick=closeForm;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeForm()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden'))closeForm()});
$('#itemForm').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button[type=submit]');submit.disabled=true;submit.textContent='جارٍ الحفظ…';try{const data=Object.fromEntries(new FormData(e.target).entries());delete data.media;let arr=store.get(page),old=editing?arr.find(x=>x.id===editing):null;if(page==='photos'){if(pendingMedia.length){if(editing){const f=pendingMedia[0],mediaId=uid();await saveMedia(mediaId,f);if(old?.mediaId)await deleteMedia(old.mediaId);arr=arr.map(x=>x.id===editing?{...x,...data,mediaId,mediaType:f.type.startsWith('video/')?'video':'image',fileName:f.name,fileSize:f.size}:x)}else{for(const f of pendingMedia){const mediaId=uid();await saveMedia(mediaId,f);arr.unshift({id:uid(),...data,mediaId,mediaType:f.type.startsWith('video/')?'video':'image',fileName:f.name,fileSize:f.size,createdAt:new Date().toISOString()})}}}else if(old){arr=arr.map(x=>x.id===editing?{...x,...data,mediaId:old.mediaId,mediaType:old.mediaType}:x)}else{toast('اختاري صورة أو فيديو أولاً');return}}if(page!=='photos'){if(editing)arr=arr.map(x=>x.id===editing?{...x,...data,updatedAt:new Date().toISOString()}:x);else arr.unshift({id:uid(),...data,done:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}if(store.set(page,arr)){const batchSaved=page==='photos'&&pendingMedia.length>1;closeForm();render();toast(batchSaved?'تمت إضافة الملفات بنجاح 🌷':'تم الحفظ بنجاح 🌷')}}catch(err){console.error(err);toast('تعذر حفظ الملف. تأكدي من مساحة الجهاز وحاولي مجدداً.')}finally{submit.disabled=false;submit.textContent='حفظ'}};
window.openForm=openForm;
let viewerIndex=0,viewerItems=[];
window.viewMedia=id=>{viewerItems=store.get('photos').filter(x=>mediaCache[x.mediaId]);viewerIndex=viewerItems.findIndex(x=>x.id===id);if(viewerIndex<0)return;showMediaViewer()};
function showMediaViewer(){const item=viewerItems[viewerIndex];if(!item)return;const body=$('#mediaViewerBody');body.innerHTML=item.mediaType==='video'?`<video class="viewer-video" src="${mediaCache[item.mediaId]}" controls autoplay playsinline preload="auto"></video>`:`<img class="viewer-image" src="${mediaCache[item.mediaId]}" alt="${esc(item.title||'صورة')}">`;$('#mediaViewerTitle').textContent=item.fileName||item.title||'بدون اسم';$('#mediaViewerCount').textContent=`${viewerIndex+1} / ${viewerItems.length}`;$('#mediaViewer').classList.remove('hidden');document.body.style.overflow='hidden';}
function closeMediaViewer(){const v=$('#mediaViewer');const video=v.querySelector('video');if(video)video.pause();v.classList.add('hidden');document.body.style.overflow=''}
function stepMedia(delta){if(!viewerItems.length)return;viewerIndex=(viewerIndex+delta+viewerItems.length)%viewerItems.length;showMediaViewer()}
$('#mediaViewerDownload').addEventListener('click',()=>{const item=viewerItems[viewerIndex];if(item)downloadMedia(item.id)});$('#closeMediaViewer').addEventListener('click',closeMediaViewer);$('#mediaPrev').addEventListener('click',()=>stepMedia(-1));$('#mediaNext').addEventListener('click',()=>stepMedia(1));$('#mediaViewer').addEventListener('click',e=>{if(e.target.id==='mediaViewer')closeMediaViewer()});document.addEventListener('keydown',e=>{if($('#mediaViewer')&&!$('#mediaViewer').classList.contains('hidden')){if(e.key==='Escape')closeMediaViewer();if(e.key==='ArrowLeft')stepMedia(1);if(e.key==='ArrowRight')stepMedia(-1)}});
window.go=go;let pendingDeleteId=null;const deleteDialog=$('#deleteConfirm');function closeDeleteDialog(){deleteDialog.classList.add('hidden');pendingDeleteId=null}$('#cancelDelete').addEventListener('click',closeDeleteDialog);deleteDialog.addEventListener('click',e=>{if(e.target===deleteDialog)closeDeleteDialog()});window.removeItem=id=>{pendingDeleteId=id;const item=store.get(page).find(x=>x.id===id);const label=page==='tasks'?'المهمة':page==='notes'?'المذكرة':'العنصر';$('#deleteTitle').textContent=`حذف ${label}؟`;$('#deleteDescription').textContent=`${item?.title?`«${item.title}» — `:''}سيُحذف نهائياً من فيروز، ولن تتمكني من استعادته.`;deleteDialog.classList.remove('hidden')};$('#confirmDelete').addEventListener('click',()=>{if(!pendingDeleteId)return;const id=pendingDeleteId,found=store.get(page).find(x=>x.id===id);if(page==='photos'&&found?.mediaId)deleteMedia(found.mediaId);store.set(page,store.get(page).filter(x=>x.id!==id));closeDeleteDialog();render();toast('تم الحذف نهائياً')});window.toggleTask=(id,v)=>{store.set('tasks',store.get('tasks').map(x=>x.id===id?{...x,done:v,completedAt:v?new Date().toISOString():null}:x));render()};window.togglePhotoFavorite=id=>{store.set('photos',store.get('photos').map(x=>x.id===id?{...x,favorite:!x.favorite}:x));renderMediaPage()};window.setDark=v=>{document.body.classList.toggle('dark',v);localStorage.setItem('fayrouz_dark',v?'1':'0')};function applyAccent(a,s){if(!/^#[0-9a-f]{6}$/i.test(String(a||'')))return;const soft=s||`color-mix(in srgb, ${a} 14%, white)`;const root=document.documentElement;root.style.setProperty('--accent',a);root.style.setProperty('--accent2',localStorage.getItem('fayrouz_accent2')||`color-mix(in srgb, ${a} 68%, white)`);root.style.setProperty('--soft',soft);root.style.setProperty('--accent-rgb',`${parseInt(a.slice(1,3),16)},${parseInt(a.slice(3,5),16)},${parseInt(a.slice(5,7),16)}`);document.querySelectorAll('.swatch').forEach(b=>b.classList.toggle('selected',(b.dataset.accent||'').toLowerCase()===a.toLowerCase()));const picker=document.querySelector('.custom-color input[type=color]');if(picker&&picker.value.toLowerCase()!==a.toLowerCase())picker.value=a;const hex=document.querySelector('#accentHex');if(hex&&hex.value.toLowerCase()!==a.toLowerCase())hex.value=a;}
window.toggleThemeStudio=()=>{const box=document.getElementById('themeStudioOptions');const btn=document.querySelector('.theme-studio-toggle');if(!box||!btn)return;const opening=box.hidden;box.hidden=!opening;btn.setAttribute('aria-expanded',String(opening));btn.querySelector('.theme-toggle-arrow').textContent=opening?'⌃':'⌄'};
window.setPalette=(a,b,soft,name)=>{if(!/^#[0-9a-f]{6}$/i.test(a)||!/^#[0-9a-f]{6}$/i.test(b))return;window.setAccent(a,soft,false);localStorage.setItem('fayrouz_accent2',b);localStorage.setItem('fayrouz_theme_name',name);document.documentElement.style.setProperty('--accent2',b);document.querySelectorAll('.palette-card').forEach(x=>x.classList.toggle('selected',x.dataset.accent.toLowerCase()===a.toLowerCase()));const n=document.querySelector('#themeName');if(n)n.textContent=name;toast('تم تطبيق لوحة '+name)};
window.setAccent=(a,s,notify=true)=>{if(!/^#[0-9a-f]{6}$/i.test(String(a||'')))return;const soft=s||`color-mix(in srgb, ${a} 14%, white)`;if(!s)localStorage.removeItem('fayrouz_accent2');applyAccent(a,soft);localStorage.setItem('fayrouz_accent',a);localStorage.setItem('fayrouz_soft',soft);localStorage.setItem('fayrouz_theme_name','لون مخصص');const n=document.querySelector('#themeName');if(n)n.textContent='لون مخصص';document.querySelectorAll('.palette-card').forEach(x=>x.classList.toggle('selected',x.dataset.accent.toLowerCase()===a.toLowerCase()));if(notify)toast('تم تطبيق اللون وحفظه فوراً')};
window.setAccentFromHex=value=>{let v=String(value||'').trim();if(!v.startsWith('#'))v='#'+v;if(/^#[0-9a-f]{6}$/i.test(v))window.setAccent(v,null,false)};
window.addEventListener('storage',e=>{if(e.key==='fayrouz_accent'||e.key==='fayrouz_soft'){applyAccent(localStorage.getItem('fayrouz_accent'),localStorage.getItem('fayrouz_soft'))}});
