// Encrypted media database: only ciphertext is written to IndexedDB.
let mediaDBPromise;
function mediaDB(){if(!mediaDBPromise)mediaDBPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('FayrouzMedia',1);req.onupgradeneeded=()=>req.result.createObjectStore('media');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return mediaDBPromise}
async function saveMedia(id,blob){const encrypted=await encryptBytes(await blob.arrayBuffer());encrypted.type=blob.type||'application/octet-stream';const db=await mediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').put(encrypted,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function getMedia(id){const db=await mediaDB();const value=await new Promise((resolve,reject)=>{const r=db.transaction('media').objectStore('media').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)});if(!value)return null;if(value instanceof Blob){const legacy=value;await saveMedia(id,legacy);return legacy}const plain=await decryptBytes(value);return new Blob([plain],{type:value.type||'application/octet-stream'})}
async function deleteMedia(id){try{const db=await mediaDB();db.transaction('media','readwrite').objectStore('media').delete(id)}catch{}}
async function renderMediaPage(){const c=$('#content');const items=store.get('photos');for(const old of Object.values(mediaCache))URL.revokeObjectURL(old);mediaCache={};for(const item of items){try{const blob=await getMedia(item.mediaId);if(blob)mediaCache[item.mediaId]=URL.createObjectURL(blob)}catch(e){console.error(e);toast('تعذر فك تشفير أحد ملفات الوسائط.')} }const images=items.filter(x=>x.mediaType==='image').length,videos=items.filter(x=>x.mediaType==='video').length;c.innerHTML=pageHead(sections.photos.title,sections.photos.sub,sections.photos.add)+`<div class="media-library-summary"><span>كل الملفات: <b>${items.length}</b></span><span>الصور: <b>${images}</b></span><span>الفيديوهات: <b>${videos}</b></span></div><div class="media-filters"><button class="${mediaFilter==='all'?'active':''}" onclick="setMediaFilter('all')">الكل</button><button class="${mediaFilter==='image'?'active':''}" onclick="setMediaFilter('image')">الصور</button><button class="${mediaFilter==='video'?'active':''}" onclick="setMediaFilter('video')">الفيديوهات</button></div>`+listHTML('photos');} 
window.setMediaFilter=f=>{mediaFilter=f;renderMediaPage()};
function safeFileName(name,fallback){const clean=String(name||fallback||'fayrouz-media').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').trim().slice(0,100);return clean||fallback||'fayrouz-media'}
window.downloadMedia=async id=>{try{const item=store.get('photos').find(x=>x.id===id);if(!item)return;const blob=await getMedia(item.mediaId);if(!blob){toast('الملف غير موجود');return}const url=URL.createObjectURL(blob),ext=(blob.type.split('/')[1]||'bin').split(';')[0].replace('jpeg','jpg');const name=safeFileName(item.fileName||item.title,`fayrouz-${item.mediaType}`);const a=document.createElement('a');a.href=url;a.download=name.includes('.')?name:`${name}.${ext}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('بدأ تحميل الملف')}catch(e){console.error(e);toast('تعذر تحميل الملف')}};

// Separate access code for the private photos/videos area.
async function photoCodeHash(value){const data=new TextEncoder().encode(String(value).trim());const digest=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function managePhotoCode(){let pin=prompt('أنشئي رمز الصور (4 أحرف أو أرقام على الأقل):');if(pin===null)return;pin=pin.trim();if(pin.length<4){toast('رمز الصور يجب أن يكون 4 أحرف أو أرقام على الأقل');return}let recovery=prompt('أنشئي رمز استعادة الصور (4 أحرف أو أرقام على الأقل):');if(recovery===null)return;recovery=recovery.trim();if(recovery.length<4||recovery===pin){toast('رمز الاستعادة يجب أن يكون 4 أحرف أو أرقام على الأقل ومختلفاً عن رمز الصور');return}try{localStorage.setItem('fayrouz_photos_pin_hash',await photoCodeHash(pin));localStorage.setItem('fayrouz_photos_recovery_hash',await photoCodeHash(recovery));toast('تم حفظ رمز الصور ورمز استعادته بنجاح')}catch(e){console.error(e);toast('تعذر حفظ رمز الصور')}}
async function unlockPhotos(){const saved=localStorage.getItem('fayrouz_photos_pin_hash');if(!saved){await managePhotoCode();return !!localStorage.getItem('fayrouz_photos_pin_hash')}const entered=prompt('أدخلي رمز الصور لفتح المعرض:');if(entered===null)return false;if(await photoCodeHash(entered)===saved)return true;const useRecovery=confirm('رمز الصور غير صحيح. هل تريدين استخدام رمز الاستعادة؟');if(!useRecovery)return false;const recovery=prompt('أدخلي رمز استعادة الصور:');if(recovery===null)return false;if(await photoCodeHash(recovery)===localStorage.getItem('fayrouz_photos_recovery_hash'))return true;toast('رمز استعادة الصور غير صحيح');return false}

// Password and recovery code independently unlock the same random AES-256 data key.
const hashSecret=async value=>{const bytes=new TextEncoder().encode(value.trim().toLowerCase());const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('')};
async function saveFounderWrappers(rawKey){const exact=await wrapVaultKey(FOUNDER_ACCESS_PHRASE,rawKey);const normalized=await wrapVaultKey(normalizeFounderPhrase(FOUNDER_ACCESS_PHRASE),rawKey);localStorage.setItem('fayrouz_key_master',JSON.stringify(exact));localStorage.setItem('fayrouz_key_master_normalized',JSON.stringify(normalized))}
async function setupVault(password,recovery){const raw=randomBytes(32);vaultKey=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},true,['encrypt','decrypt']);const p=await wrapVaultKey(password,raw),r=await wrapVaultKey(recovery,raw);localStorage.setItem('fayrouz_key_password',JSON.stringify(p));localStorage.setItem('fayrouz_key_recovery',JSON.stringify(r));await saveFounderWrappers(raw);await loadVault();localStorage.removeItem('fayrouz_auth_password');localStorage.removeItem('fayrouz_auth_recovery')}
async function openVault(secret){const entered=String(secret??'');const records=[localStorage.getItem('fayrouz_key_password'),localStorage.getItem('fayrouz_key_recovery'),localStorage.getItem('fayrouz_key_master')].filter(Boolean);for(const raw of records){try{vaultKey=await unwrapVaultKey(entered,JSON.parse(raw));await loadVault();return true}catch{vaultKey=null}}if(normalizeFounderPhrase(entered)===normalizeFounderPhrase(FOUNDER_ACCESS_PHRASE)){const normalizedRecord=localStorage.getItem('fayrouz_key_master_normalized');if(normalizedRecord){try{vaultKey=await unwrapVaultKey(normalizeFounderPhrase(entered),JSON.parse(normalizedRecord));await loadVault();return true}catch{vaultKey=null}}}return false}
async function ensureFounderAccess(){const raw=await crypto.subtle.exportKey('raw',vaultKey);await saveFounderWrappers(raw)}
function authOverlay(){if(!globalThis.crypto?.subtle){document.body.insertAdjacentHTML('beforeend','<div class="auth-screen"><div class="auth-card"><h1>Fayrouz</h1><p>التشفير غير متاح في طريقة فتح التطبيق الحالية. افتحيه باستخدام متصفح Chrome أو Edge حديث ومن خلال HTTPS أو localhost.</p></div></div>');return}const encrypted=!!localStorage.getItem('fayrouz_key_password'),legacy=!!localStorage.getItem('fayrouz_auth_password');const configured=encrypted||legacy;document.body.insertAdjacentHTML('beforeend',`<div class="auth-screen" id="authScreen"><div class="auth-card"><div class="auth-logo">F</div><p class="auth-kicker">مساحتكِ الخاصة</p><h1>Fayrouz</h1><p id="authMessage">${encrypted?'أدخلي رمز الدخول لفتح مساحتكِ':'أنشئي بيانات الدخول لتشفير مساحتكِ'}</p><form id="authForm">${encrypted?'<label>رمز الدخول<input id="authPassword" type="password" required autocomplete="current-password" autofocus></label>':legacy?'<label>كلمة المرور أو رمز الاستعادة الحالية<input id="legacySecret" type="password" required></label><label>كلمة المرور الجديدة<input id="authPassword" type="password" minlength="8" required></label><label>رمز الاستعادة الجديد<input id="authRecovery" type="password" minlength="4" required></label>':'<label>كلمة المرور الجديدة<input id="authPassword" type="password" minlength="8" required autocomplete="new-password"></label><label>تأكيد كلمة المرور<input id="authConfirm" type="password" minlength="8" required></label><label>رمز الاستعادة (احفظيه في مكان آمن)<input id="authRecovery" type="password" minlength="4" required autocomplete="off"></label>'}<button class="btn primary auth-submit">${configured?'دخول':'تفعيل التشفير'}</button></form>${encrypted?'<button type="button" class="text-link auth-forgot" id="forgotAccess">نسيت كلمة المرور؟ استخدم رمز الاستعادة</button><form id="recoveryForm" class="hidden"><label>رمز الاستعادة<input id="recoveryInput" type="password" minlength="4" required autocomplete="off"></label><button class="btn primary auth-submit" type="submit">فتح باستخدام رمز الاستعادة</button></form>':''}<small class="auth-note">تُشفّر البيانات والوسائط على هذا الجهاز ولا تُرفع إلى أي خادم.</small></div></div>`);$('#authForm').onsubmit=async e=>{e.preventDefault();const btn=$('#authForm button');btn.disabled=true;try{if(encrypted){if(await openVault($('#authPassword').value)){await ensureFounderAccess();await finishUnlock()}else if(normalizeFounderPhrase($('#authPassword').value)===normalizeFounderPhrase(FOUNDER_ACCESS_PHRASE)&&!localStorage.getItem('fayrouz_key_master')){toast('هذا القفل أُنشئ في إصدار أقدم. افتحيه مرة واحدة بكلمة المرور أو رمز الاستعادة القديم لتفعيل الرمز الرئيسي على بياناتك الحالية.')}else toast('بيانات الدخول غير صحيحة');}else if(legacy){const entered=await hashSecret($('#legacySecret').value);if(entered!==localStorage.getItem('fayrouz_auth_password')&&entered!==localStorage.getItem('fayrouz_auth_recovery')){toast('بيانات الدخول الحالية غير صحيحة');return}const pw=$('#authPassword').value,rec=$('#authRecovery').value;if(pw.length<8||rec.length<4||pw===rec){toast('كلمة المرور 8 أحرف على الأقل، ورمز الاستعادة 4 أحرف أو أكثر، ويجب أن يختلفا');return}await setupVault(pw,rec);await finishUnlock()}else{const pw=$('#authPassword').value,rec=$('#authRecovery').value;if(pw!==$('#authConfirm').value){toast('كلمتا المرور غير متطابقتين');return}if(pw.length<8||rec.length<4||pw===rec){toast('كلمة المرور 8 أحرف على الأقل، ورمز الاستعادة 4 أحرف أو أكثر، ويجب أن يختلفا');return}await setupVault(pw,rec);await finishUnlock()}}catch(err){console.error(err);toast('تعذر فتح الخزنة المشفّرة. تأكدي من كلمة المرور أو رمز الاستعادة.')}finally{btn.disabled=false}};if(encrypted){$('#forgotAccess').onclick=()=>{$('#recoveryForm').classList.toggle('hidden');if(!$('#recoveryForm').classList.contains('hidden'))$('#recoveryInput').focus()};$('#recoveryForm').onsubmit=async e=>{e.preventDefault();const btn=$('#recoveryForm button');btn.disabled=true;try{if(await openVault($('#recoveryInput').value)){await ensureFounderAccess();await finishUnlock()}else if(normalizeFounderPhrase($('#recoveryInput').value)===normalizeFounderPhrase(FOUNDER_ACCESS_PHRASE)&&!localStorage.getItem('fayrouz_key_master')){toast('هذا القفل أُنشئ في إصدار أقدم. افتحيه مرة واحدة بكلمة المرور أو رمز الاستعادة القديم لتفعيل الرمز الرئيسي على بياناتك الحالية.')}else toast('رمز الاستعادة غير صحيح')}catch(err){console.error(err);toast('تعذر التحقق من رمز الاستعادة')}finally{btn.disabled=false}}}}
async function migrateAllMedia(){const db=await mediaDB();const all=await new Promise((resolve,reject)=>{const tx=db.transaction('media','readonly'),req=tx.objectStore('media').getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)});const keys=await new Promise((resolve,reject)=>{const tx=db.transaction('media','readonly'),req=tx.objectStore('media').getAllKeys();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)});for(let i=0;i<all.length;i++){if(all[i] instanceof Blob)await saveMedia(keys[i],all[i])}}
async function finishUnlock(){await migrateAllMedia();$('#authScreen')?.remove();if(localStorage.getItem('fayrouz_dark')==='1')document.body.classList.add('dark');if(localStorage.getItem('fayrouz_large_text')==='1')document.body.classList.add('large-text');const a=localStorage.getItem('fayrouz_accent');if(a){document.documentElement.style.setProperty('--accent',a);document.documentElement.style.setProperty('--accent2',localStorage.getItem('fayrouz_accent2')||`color-mix(in srgb, ${a} 65%, white)`);document.documentElement.style.setProperty('--soft',localStorage.getItem('fayrouz_soft')||`color-mix(in srgb, ${a} 13%, white)`)}render();toast('تم فتح المساحة المشفّرة بنجاح')}
// Each security setting opens only its own form.
async function saveVaultCredential(kind){
 if(!vaultKey){toast('افتحي التطبيق أولاً لإدارة الحماية');return}
 const isPassword=kind==='password';
 document.getElementById('credentialDialog')?.remove();
 const title=isPassword?'تغيير كلمة المرور':'تغيير رمز الاستعادة';
 const fieldLabel=isPassword?'كلمة المرور الجديدة':'رمز الاستعادة الجديد';
 const inputId=isPassword?'newCredentialPassword':'newCredentialRecovery';
 const confirmField=isPassword?'<label class="credential-field">تأكيد كلمة المرور<input id="confirmCredentialPassword" type="password" minlength="4" required autocomplete="new-password" placeholder="أعيدي كتابة كلمة المرور"></label>':'';
 document.body.insertAdjacentHTML('beforeend',`<div class="credential-dialog" id="credentialDialog" role="dialog" aria-modal="true" aria-labelledby="credentialTitle"><form class="credential-card" id="credentialForm"><button class="credential-close" type="button" aria-label="إغلاق" id="credentialClose">×</button><div class="credential-icon">${isPassword?'♧':'⌑'}</div><p class="credential-kicker">حماية فيروز</p><h2 id="credentialTitle">${title}</h2><p class="credential-description">${isPassword?'اختاري كلمة مرور جديدة للدخول إلى تطبيق فيروز.':'اختاري رمزاً جديداً لاستخدامه عند نسيان كلمة المرور.'}</p><label class="credential-field">${fieldLabel}<input id="${inputId}" type="password" minlength="4" required autocomplete="new-password" placeholder="4 أحرف أو أرقام على الأقل"></label>${confirmField}<small class="credential-hint">${isPassword?'يجب أن تتكون كلمة المرور من 4 أحرف أو أرقام على الأقل.':'يجب أن يتكون رمز الاستعادة من 4 أحرف أو أرقام على الأقل، وأن يختلف عن كلمة المرور.'}</small><div class="credential-actions"><button class="btn ghost" type="button" id="credentialCancel">إلغاء</button><button class="btn primary" type="submit" id="credentialSave">حفظ</button></div></form></div>`);
 const dialog=$('#credentialDialog'),form=$('#credentialForm'),close=()=>dialog.remove();
 $('#credentialClose').onclick=close;$('#credentialCancel').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog)close()});$('#'+inputId).focus();
 form.onsubmit=async e=>{
  e.preventDefault();const value=$('#'+inputId).value.trim(),btn=$('#credentialSave');
  if(value.length<4){toast('يجب إدخال 4 أحرف أو أرقام على الأقل');return}
  if(isPassword&&value!==$('#confirmCredentialPassword').value){toast('تأكيد كلمة المرور غير مطابق');$('#confirmCredentialPassword').focus();return}
  try{const other=JSON.parse(localStorage.getItem(isPassword?'fayrouz_key_recovery':'fayrouz_key_password')||'null');if(other){await unwrapVaultKey(value,other);toast('يجب أن تختلف كلمة المرور عن رمز الاستعادة');return}}catch{}
  btn.disabled=true;
  try{const raw=await crypto.subtle.exportKey('raw',vaultKey),record=await wrapVaultKey(value,raw);localStorage.setItem(isPassword?'fayrouz_key_password':'fayrouz_key_recovery',JSON.stringify(record));close();toast(isPassword?'تم تغيير كلمة المرور بنجاح':'تم تغيير رمز الاستعادة بنجاح')}
  catch(err){console.error(err);toast('تعذر تحديث بيانات الحماية')}
  finally{if(document.body.contains(btn))btn.disabled=false}
 };
}
window.changePassword=()=>saveVaultCredential('password');
window.changeRecoveryCode=()=>saveVaultCredential('recovery');
// Backward-compatible entry point for older saved UI references.
window.changeCredentials=()=>saveVaultCredential('password');

if(localStorage.getItem('fayrouz_dark')==='1')document.body.classList.add('dark');if(localStorage.getItem('fayrouz_large_text')==='1')document.body.classList.add('large-text');const savedAccent=localStorage.getItem('fayrouz_accent')||getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();applyAccent(savedAccent,localStorage.getItem('fayrouz_soft')||null);authOverlay();
